import{_ as n}from"./chunks/harness-layers.BAdJY8wf.js";import{_ as o,C as i,o as l,c,j as a,a as t,E as d,a6 as e}from"./chunks/framework.jAo0vQjE.js";const k=JSON.parse('{"title":"Agent Harness","description":"Everything a coding agent adds around the model and its core loop: system prompt, instruction files, tools and MCP, skills, plan mode, subagents, hooks, and context management such as compaction.","frontmatter":{"schema_version":1,"id":"concept-agent-harness","type":"concept","slug":"agent-harness","title":"Agent Harness","summary":"Everything a coding agent adds around the model and its core loop: system prompt, instruction files, tools and MCP, skills, plan mode, subagents, hooks, and context management such as compaction.","topics":["ai-agents","coding-agents","context-engineering"],"status":"reviewed","review":{"reviewed_on":"2026-11-07T00:00:00.000Z","notes":"Publication approved by the owner on 2026-11-07 (approval covering all imported Phase 07 pages, given in the deployment session). The text is AI-assisted; see authorship."},"visibility":"public","publication":"published","created":"2026-11-07T00:00:00.000Z","updated":"2026-11-07T00:00:00.000Z","authorship":{"author":"owner","ai_involvement":"assisted"},"rights":"own","aliases":["coding agent harness","agent scaffold"],"prerequisites":["concept-agent-loop","concept-tool-calling"],"related":["concept-agent-instruction-files","concept-model-context-protocol","lecture-stanford-cs146s-02","paper-harnesssecurity-bench","paper-agent-retrieval-bench","paper-seeing-like-an-agent","concept-agent-skills","concept-subagents","concept-context-compaction","concept-loop-engineering"],"sources":[{"key":"cs146s-0924","title":"The Anatomy of a Modern Coding Agent (CS146S, Fall 2026, lecture of 2026-09-24)","kind":"lecture","authors":["Mihail Eric"],"year":2026,"url":"https://themodernsoftware.dev/materials/9-24-26-transcript.txt","accessed":"2026-11-07T00:00:00.000Z","note":"Official transcript and slides checked; locators are transcript timestamps."}]},"headers":[],"relativePath":"concepts/agent-harness.md","filePath":"concepts/agent-harness.md"}'),p={name:"concepts/agent-harness.md"};function g(h,s,u,m,f,E){const r=i("AtlasPageHeader");return l(),c("div",null,[s[0]||(s[0]=a("h1",{id:"agent-harness",tabindex:"-1"},[t("Agent Harness "),a("a",{class:"header-anchor",href:"#agent-harness","aria-label":'Permalink to "Agent Harness"'},"​")],-1)),d(r),s[1]||(s[1]=a("h2",{id:"definition",tabindex:"-1"},[t("Definition "),a("a",{class:"header-anchor",href:"#definition","aria-label":'Permalink to "Definition"'},"​")],-1)),s[2]||(s[2]=a("div",{class:"atlas-callout atlas-callout--definition",role:"note"},[a("p",{class:"atlas-callout-title"},"Definition: Agent harness"),a("p",{dir:"rtl",lang:"ar-EG"},[t("الـ agent harness هو كل الكود والتعليمات اللي حوالين الموديل: الـ system prompt، وملفات التعليمات زي "),a("code",null,"AGENTS.md"),t('، وقايمة الأدوات، والأوضاع زي plan mode، والـ subagents، والـ skills، والـ hooks، والـ compaction. الموديل هو "الذكاء"، والـ harness هو اللي بيحدد الموديل يشوف إيه، ويقدر يعمل إيه، وشغله بيتنظم إزاي '),a("span",{class:"atlas-citation"},[t("["),a("a",{href:"#source-cs146s-0924"},"cs146s-0924"),t("]")]),t(".")])],-1)),s[3]||(s[3]=e('<p dir="rtl" lang="ar-EG">الـ agent loop جزء من الـ harness، مش العكس. والمحاضر بيعتبر تصميم الـ harness من أهم المشاكل في الـ coding agents النهارده <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG">تعدّد مكونات الـ harness وتشرح دور كل واحد في جملة.</li><li dir="rtl" lang="ar-EG">تفرّق بين اللي بيحدده الـ harness (system prompt) واللي إنت بتتحكم فيه (<code>AGENTS.md</code>، skills، hooks).</li><li dir="rtl" lang="ar-EG">تشرح ليه &quot;أدوات أقل وأقوى&quot; مبدأ تصميم مش مجرد ذوق.</li></ul><h2 id="intuition" tabindex="-1">Intuition <a class="header-anchor" href="#intuition" aria-label="Permalink to &quot;Intuition&quot;">​</a></h2><p dir="rtl" lang="ar-EG">تخيل الموديل مهندس شاطر لسه واصل الشركة النهارده. الـ harness هو كل اللي الشركة بتديهوله: كتيّب القواعد (system prompt)، وملف الفريق اللي فيه ستايل المشروع (<code>AGENTS.md</code>)، والصلاحيات والأدوات (tools وMCP)، وإجراءات مكتوبة لمهام متكررة (skills)، وزملا يقدر يوزع عليهم شغل (subagents)، ونظام بيلخص اجتماعات النهارده عشان ماينساش (compaction).</p><p dir="rtl" lang="ar-EG">نفس المهندس في شركتين مختلفتين هيشتغل بجودة مختلفة. ونفس الموديل في harnesses مختلفة كمان.</p><h2 id="formal-explanation" tabindex="-1">Formal explanation <a class="header-anchor" href="#formal-explanation" aria-label="Permalink to &quot;Formal explanation&quot;">​</a></h2><figure class="atlas-figure"><img src="'+n+'" alt="The core agent loop in the middle, surrounded by three groups: instructions (system prompt, AGENTS.md or CLAUDE.md, skills), capabilities (built-in tools, MCP servers, subagents), and work management (plan mode, hooks, compaction)" loading="lazy"><figcaption dir="rtl" lang="ar-EG">مكونات الـ harness اللي المحاضرة عرضتها، متجمعة حسب وظيفتها: تعليمات داخلة للموديل، وقدرات طالعة منه، وإدارة للشغل. التجميع ده تنظيم شخصي للشرح، مش من الـ slides. Source: own diagram.</figcaption></figure><table tabindex="0"><thead><tr><th>Component</th><th>Role</th><th>Who controls it</th></tr></thead><tbody><tr><td>System prompt</td><td dir="rtl" lang="ar-EG">blueprint لسلوك الموديل: الـ harness، والـ guardrails، ومعلومات البيئة <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>, 34:30]</span></td><td dir="rtl" lang="ar-EG">الـ harness (static، بيتحقن من غير ما تشوفه)</td></tr><tr><td><code>AGENTS.md</code> / <code>CLAUDE.md</code></td><td dir="rtl" lang="ar-EG">تعليمات المشروع؛ النسخة اللي إنت بتتحكم فيها من الـ system prompt <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>, 44:22]</span></td><td dir="rtl" lang="ar-EG">إنت أو الفريق</td></tr><tr><td>Tool list</td><td dir="rtl" lang="ar-EG">أسماء وأوصاف وsignatures الأدوات، وبتتبعت مع كل request، ومعاها أدوات الـ MCP <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>, 25:58]</span></td><td dir="rtl" lang="ar-EG">الـ harness + الـ MCP servers اللي ضفتها</td></tr><tr><td>Plan mode</td><td dir="rtl" lang="ar-EG">وضع لتطوير spec والنقاش مع المستخدم قبل التنفيذ؛ عبارة عن prompt وأداة للدخول فيه <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span></td><td dir="rtl" lang="ar-EG">الـ harness؛ إنت بتشغّله</td></tr><tr><td>Skills</td><td dir="rtl" lang="ar-EG">إجراء مكتوب؛ في الأول بيظهر الـ metadata بس، والتفاصيل بتتحمل لما تبقى مهمة (progressive disclosure) <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>, 25:58]</span></td><td dir="rtl" lang="ar-EG">إنت</td></tr><tr><td>Subagents</td><td dir="rtl" lang="ar-EG">workers بيتنادوا بـ tool call، كل واحد بـ fresh context، وبيرجّعوا النتيجة للـ orchestrator <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>, 53:40]</span></td><td dir="rtl" lang="ar-EG">الـ harness؛ إنت ممكن تعرّف أنواع</td></tr><tr><td>Hooks</td><td dir="rtl" lang="ar-EG">prompts أو كود بيتحط في نقط معينة من دورة حياة الـ harness <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span></td><td dir="rtl" lang="ar-EG">إنت</td></tr><tr><td>Compaction</td><td dir="rtl" lang="ar-EG">تلخيص الـ history لما تقرب تعدّي الـ context window، والملخص بيحل محلها <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>, 55:25]</span></td><td dir="rtl" lang="ar-EG">تلقائي أو يدوي</td></tr></tbody></table><h3 id="design-principle-simplicity" tabindex="-1">Design principle: simplicity <a class="header-anchor" href="#design-principle-simplicity" aria-label="Permalink to &quot;Design principle: simplicity&quot;">​</a></h3><p dir="rtl" lang="ar-EG">المحاضر بيلخص اتجاه الصناعة في <strong>simplicity</strong>: أدوات أقل وأقوى، زي Bash وSQL، لأن أداة زي Bash عمليًا لغة كاملة لوحدها. والـ 40 أداة تقريبًا اللي في Claude Code أقل من نسخ أقدم من نفس الـ harness. ونصيحته لو بتبني harness: ابدأ بتلات لخمس أدوات بيعملوا كتير، ووسّع بعدين <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>.</p><p dir="rtl" lang="ar-EG">السبب الأعمق إن كل أداة بتاكل جزء من الـ context في كل request، والـ context الزحمة بتوصّل الموديل لما المحاضر بيسميه بشكل غير رسمي &quot;dumb zone&quot;: المنطقة اللي الموديل بيبدأ يبقى فيها أقل كفاءة <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>. وعشان كده كمان الاتجاه الحالي نحو prompts أقصر <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>.</p><h2 id="diagram" tabindex="-1">Diagram <a class="header-anchor" href="#diagram" aria-label="Permalink to &quot;Diagram&quot;">​</a></h2><p dir="rtl" lang="ar-EG">الرسمة فوق هي الـ overview. التفاصيل التنفيذية (subagents، compaction، شكل الـ trace) في <a href="./../lectures/stanford-cs146s/stanford-cs146s-02">The Anatomy of a Modern Coding Agent</a>.</p><h2 id="limitations-and-common-misconceptions" tabindex="-1">Limitations and common misconceptions <a class="header-anchor" href="#limitations-and-common-misconceptions" aria-label="Permalink to &quot;Limitations and common misconceptions&quot;">​</a></h2><ul dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG"><strong>&quot;A harness is a framework like LangGraph.&quot;</strong> مش لازم. الـ harness هو كل اللي حوالين الموديل في أي agent، سواء مكتوب بإيدك أو جاي جاهز.</li><li dir="rtl" lang="ar-EG"><strong>&quot;More components means a better agent.&quot;</strong> المحاضرة بتقول العكس: الاتجاه نحو البساطة، وكل مكون بيدفع من الـ context <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>.</li><li dir="rtl" lang="ar-EG"><strong>&quot;Plan mode is a different model.&quot;</strong> في الـ trace اللي اتعرض، الـ plan mode هو حرفيًا block من النص وأداة للدخول فيه <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>.</li><li dir="rtl" lang="ar-EG"><strong>&quot;Compaction is free.&quot;</strong> الملخص بيحل محل الأصل، فأي تفصيلة مادخلتش في الملخص ضاعت. والـ slides بتقول إنه &quot;can be lossy&quot; <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>.</li><li dir="rtl" lang="ar-EG">الأرقام زي &quot;40 أداة&quot; بتتغير مع كل إصدار. المهم الفكرة، مش العدد.</li></ul><h2 id="exercises" tabindex="-1">Exercises <a class="header-anchor" href="#exercises" aria-label="Permalink to &quot;Exercises&quot;">​</a></h2>',17)),s[4]||(s[4]=a("div",{class:"atlas-callout atlas-callout--exercise",role:"note"},[a("p",{class:"atlas-callout-title"},"Exercise: Classify the components"),a("p",{dir:"rtl",lang:"ar-EG"},[t("لكل مكون من دول قول: بيغيّر الموديل "),a("strong",null,"يعرف إيه"),t("، ولا "),a("strong",null,"يقدر يعمل إيه"),t("، ولا "),a("strong",null,"الشغل بيتنظم إزاي"),t("؟ "),a("code",null,"CLAUDE.md"),t("، MCP server، skill، subagent، compaction، hook بيشغّل الـ tests بعد كل تعديل.")]),a("details",{class:"details custom-block"},[a("summary",null,"Solution"),a("p",{dir:"rtl",lang:"ar-EG"},[a("code",null,"CLAUDE.md"),t(": يعرف إيه. MCP server: يقدر يعمل إيه. Skill: الاتنين (معرفة بإجراء، وغالبًا بيستخدم أدوات). Subagent: يقدر يعمل إيه، وبيحمي الـ context كمان. Compaction: تنظيم الشغل. الـ hook: تنظيم الشغل (بيتنفذ في نقطة ثابتة من دورة الـ harness، مش بقرار من الموديل).")])])],-1)),s[5]||(s[5]=a("div",{class:"atlas-callout atlas-callout--takeaways",role:"note"},[a("p",{class:"atlas-callout-title"},"Key takeaways"),a("ul",{dir:"rtl",lang:"ar-EG"},[a("li",{dir:"rtl",lang:"ar-EG"},"الـ harness = كل اللي حوالين الموديل؛ الـ loop جزء منه."),a("li",{dir:"rtl",lang:"ar-EG"},[t("الـ system prompt بيحدده الـ harness، و"),a("code",null,"AGENTS.md"),t("/"),a("code",null,"CLAUDE.md"),t(" إنت اللي بتحدده.")]),a("li",{dir:"rtl",lang:"ar-EG"},"كل أداة وكل تعليمة بتدفع من الـ context في كل request."),a("li",{dir:"rtl",lang:"ar-EG"},"المبدأ: أدوات أقل وأقوى، وprompts أقصر، وتحميل التفاصيل وقت الحاجة.")])],-1)),s[6]||(s[6]=e('<h2 id="review-questions" tabindex="-1">Review questions <a class="header-anchor" href="#review-questions" aria-label="Permalink to &quot;Review questions&quot;">​</a></h2><ol dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG">ليه الـ agent loop جزء من الـ harness ومش العكس؟</li><li dir="rtl" lang="ar-EG">إيه الفرق بين الـ system prompt و<code>AGENTS.md</code> من حيث مين بيتحكم فيه وإمتى بيتحقن؟</li><li dir="rtl" lang="ar-EG">ليه Bash بيعتبر أداة &quot;قوية&quot;؟ وإيه خطورة ده؟</li><li dir="rtl" lang="ar-EG">إزاي الـ skills والـ subagents الاتنين بيساعدوا في إدارة الـ context بطريقتين مختلفتين؟</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p dir="rtl" lang="ar-EG">المحاضرة <span class="atlas-citation">[<a href="#source-cs146s-0924">cs146s-0924</a>]</span>. الشرح المفصل في <a href="./../lectures/stanford-cs146s/stanford-cs146s-02">The Anatomy of a Modern Coding Agent</a>.</p>',4))])}const q=o(p,[["render",g]]);export{k as __pageData,q as default};
